import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第二十四卦 复 地雷复 坤上震下","description":"周易 - 第二十四卦 复 地雷复 坤上震下","frontmatter":{"title":"第二十四卦 复 地雷复 坤上震下","description":"周易 - 第二十四卦 复 地雷复 坤上震下"},"headers":[],"relativePath":"zh/classics/zhouyi/025.md","filePath":"zh/classics/zhouyi/025.md"}'),l={name:"zh/classics/zhouyi/025.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="复" tabindex="-1">复 <a class="header-anchor" href="#复" aria-label="Permalink to “复”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>亨。出入无疾，朋来无咎。反复其道，七日来复，利有攸往。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>复亨；刚反，动而以顺行，是以出入无疾，朋来无咎。反复其道，七日来复，天行也。利有攸往，刚长也。复其见天地之心乎？</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>雷在地中，复；先王以至日闭关，商旅不行，后不省方。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>不复远，无只 悔，元吉。象曰：不远之复，以修身也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>休复，吉。象曰：休复之吉，以下仁也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>频复，厉无咎。象曰：频复之厉，义无咎也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>中行独复。象曰：中行独复，以从道也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>敦复，无悔。象曰：敦复无悔，中以自考也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>迷复，凶，有灾眚。用行师，终有大败，以其国君，凶；至于十年，不克征。象曰：迷复之凶，反君道也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
